import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>

__global__ void cumulative_product_kernel(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t dim_size,
    int64_t stride,
    int64_t batch_size
) {
    int64_t batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const half* input_batch = input + batch_idx * dim_size * stride;
    half* output_batch = output + batch_idx * dim_size * stride;

    // Process each element along the specified dimension
    for (int64_t i = 0; i < dim_size; i++) {
        if (i == 0) {
            // First element: copy directly
            for (int64_t j = 0; j < stride; j++) {
                output_batch[i * stride + j] = input_batch[i * stride + j];
            }
        } else {
            // Subsequent elements: multiply with previous cumulative product
            for (int64_t j = 0; j < stride; j++) {
                output_batch[i * stride + j] = __hmul(
                    output_batch[(i-1) * stride + j],
                    input_batch[i * stride + j]
                );
            }
        }
    }
}

// Optimized version for better memory access patterns
__global__ void cumulative_product_kernel_optimized(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t dim_size,
    int64_t stride,
    int64_t batch_size
) {
    int64_t batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const half* input_batch = input + batch_idx * dim_size * stride;
    half* output_batch = output + batch_idx * dim_size * stride;

    // Process elements in a more cache-friendly manner
    for (int64_t j = 0; j < stride; j++) {
        half cumprod = input_batch[j];
        output_batch[j] = cumprod;

        for (int64_t i = 1; i < dim_size; i++) {
            cumprod = __hmul(cumprod, input_batch[i * stride + j]);
            output_batch[i * stride + j] = cumprod;
        }
    }
}
"""

# Python wrapper
def compile_and_run():
    # Compile the CUDA extension
    module = load_inline(
        name="cumulative_product_cuda",
        cpp_sources=[],
        cuda_sources=[cuda_source],
        functions=["cumulative_product_kernel_optimized"],
        verbose=False
    )

    return module

# Model implementation using the CUDA kernel
class ModelNew(torch.nn.Module):
    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.cuda_module = compile_and_run()

    def forward(self, x):
        # Get tensor properties
        shape = x.shape
        batch_size = 1
        dim_size = shape[self.dim]
        stride = 1

        # Calculate stride for the specified dimension
        for i in range(self.dim + 1, len(shape)):
            stride *= shape[i]

        # Calculate batch size (product of all dimensions except the target one)
        for i in range(len(shape)):
            if i != self.dim:
                batch_size *= shape[i]

        # Prepare output tensor
        output = torch.empty_like(x)

        # Launch kernel
        grid_size = batch_size
        block_size = 1

        self.cuda_module.cumulative_product_kernel_optimized(
            x.contiguous().data_ptr(),
            output.data_ptr(),
            int(x.numel()),
            int(dim_size),
            int(stride),
            int(batch_size)
        )

        return output

# Define input dimensions and parameters
batch_size = 32768
input_shape = (32768,)
dim = 1

def get_inputs():
    return [torch.rand(batch_size, *input_shape, dtype=torch.float16)]

def get_init_inputs():
    return [dim]
